def icon(name: str, size: int = 22) -> Markup:
    body = ICONS.get(name)
    if not body:
        return Markup("")
    px = int(size)
    if px < 12 or px > 40:
        px = 22
    return Markup(
        '<svg class="ico" viewBox="0 0 24 24" width="%d" height="%d" aria-hidden="true" focusable="false">%s</svg>' % (px, px, body)
    )
